question:
Cài đặt radix sort sau có lỗi. Lỗi đó là gì?
`function radixSort(nums) {
  const buckets = Array.from({ length: 10 }, () => []);
  for (let k = 0; k < mostDigits(nums); k++) {
    for (const num of nums) {
      buckets[getDigit(num, k)].push(num);
    }
    nums = [].concat(...buckets);
  }
  return nums;
}`

